-- M2: time-limited, single-use invite links.
--
-- The secret in the link is generated by create_invite, returned once and
-- never stored: the table only keeps its sha256.

create table public.invites (
  id uuid primary key default gen_random_uuid(),
  household_id uuid not null references public.households (id) on delete cascade,
  token_hash bytea not null unique,
  created_by uuid references auth.users (id) on delete set null,
  created_at timestamptz not null default now(),
  expires_at timestamptz not null,
  accepted_by uuid references auth.users (id) on delete set null,
  accepted_at timestamptz,
  revoked_at timestamptz
);

create index invites_household_id_idx on public.invites (household_id);

alter table public.invites enable row level security;

revoke all on table public.invites from anon, authenticated;
-- token_hash is deliberately not readable by clients.
grant select (id, household_id, created_by, created_at, expires_at,
              accepted_by, accepted_at, revoked_at)
  on table public.invites to authenticated;
grant update (revoked_at) on table public.invites to authenticated;

create policy "admins read their household's invites"
  on public.invites for select to authenticated
  using ((select private.is_admin(household_id)));

create policy "admins revoke their household's invites"
  on public.invites for update to authenticated
  using ((select private.is_admin(household_id)))
  with check ((select private.is_admin(household_id)));

-- Clients can only revoke: the time is set here and a revocation is final.
create function private.invites_guard_update()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if current_user = 'authenticated' then
    new.revoked_at := coalesce(old.revoked_at, now());
  end if;
  return new;
end;
$$;

revoke all on function private.invites_guard_update() from public;

create trigger invites_guard_update
  before update on public.invites
  for each row execute function private.invites_guard_update();

-- ---------------------------------------------------------------------------
-- create_invite: admins only. Returns the secret for the link, once.

create function public.create_invite(target_household uuid)
returns text
language plpgsql
volatile
security definer
set search_path = ''
as $$
declare
  caller uuid := auth.uid();
  secret text;
begin
  if caller is null or not private.is_admin(target_household) then
    raise exception 'only admins can invite' using errcode = '42501';
  end if;

  -- 32 random bytes, base64url without padding (43 characters).
  secret := rtrim(translate(encode(extensions.gen_random_bytes(32), 'base64'), '+/', '-_'), '=');

  insert into public.invites (household_id, token_hash, created_by, expires_at)
  values (target_household, extensions.digest(secret, 'sha256'), caller, now() + interval '3 days');

  return secret;
end;
$$;

-- ---------------------------------------------------------------------------
-- accept_invite: joins the caller to the household as member. Every reason
-- an invite can't be used gives the same error, so a link never reveals
-- which household it belongs to or why it failed.

create function public.accept_invite(token text)
returns uuid
language plpgsql
volatile
security definer
set search_path = ''
as $$
declare
  caller uuid := auth.uid();
  invite public.invites;
begin
  if caller is null then
    raise exception 'not signed in' using errcode = '42501';
  end if;

  select * into invite
  from public.invites i
  where i.token_hash = extensions.digest(coalesce(token, ''), 'sha256')
  for update;

  if not found then
    raise exception 'invite_invalid' using errcode = 'P0001';
  end if;

  -- Already a member (including someone opening their own used link
  -- again): nothing to do, and the invite is not consumed.
  if exists (
    select 1 from public.members m
    where m.household_id = invite.household_id and m.user_id = caller
  ) then
    return invite.household_id;
  end if;

  if invite.revoked_at is not null
     or invite.accepted_at is not null
     or invite.expires_at <= now() then
    raise exception 'invite_invalid' using errcode = 'P0001';
  end if;

  insert into public.members (household_id, user_id, role, display_name)
  values (invite.household_id, caller, 'member', private.default_display_name(caller));

  update public.invites
  set accepted_by = caller, accepted_at = now()
  where id = invite.id;

  return invite.household_id;
end;
$$;

-- See create_household for why anon may execute these.
revoke execute on function public.create_invite(uuid) from public;
revoke execute on function public.accept_invite(text) from public;
grant execute on function public.create_invite(uuid) to anon, authenticated;
grant execute on function public.accept_invite(text) to anon, authenticated;
